import{t as e}from"./jsx-runtime-lw2jiZar.js";import{A as t,C as n,E as r,M as i,N as a,O as o,P as s,S as c,b as l,k as u,l as d,n as f,o as p,t as m,x as h}from"./shared-pB8LFUv2.js";import{t as g}from"./database-LLH4Psoh.js";import{t as _}from"./file-check-2-CjevUofJ.js";import{D as v}from"./index-J3P0holD.js";var y=e(),b=`Глава 4 · Блок 15 · Готовность к переходу на SQL`;function x({module:e}){return(0,y.jsxs)(a,{children:[(0,y.jsx)(i,{variant:`project`,chip:e??b,title:`Готовность к переходу`,intro:`Соберём доказательства, что API и CLI могут работать с одним SQL-хранилищем на изолированной копии данных. Штатный Planner пока остаётся на JSON.`,tags:[{icon:(0,y.jsx)(_,{size:14}),label:`приёмка пути`},{icon:(0,y.jsx)(g,{size:14}),label:`тестовая SQLite`},{icon:(0,y.jsx)(v,{size:14}),label:`без переключения`}]}),(0,y.jsxs)(s,{number:`00`,title:`Проверяем готовность до переноса данных`,children:[(0,y.jsx)(o,{children:`Planner уже умеет хранить задачи постоянно, а SQL-путь готовился по частям. Теперь проверим, согласованы ли операции, настройки и ресурсы API с CLI. Это занятие не переносит рабочие записи и не назначает SQLite штатным источником.`}),(0,y.jsx)(u,{variant:`connected`,items:[{title:`Точка старта`,description:`JSON остаётся рабочим хранилищем. SQL CRUD, поиск, выборка, provider API, ресурс CLI и импорт должны быть подтверждены предыдущими шагами.`},{title:`Новый вопрос`,description:`Доказывают ли отдельные проверки, что оба интерфейса видят одни данные и сохраняют прежний договор после нового запроса или команды?`},{title:`Результат`,description:`На отдельной SQLite получаем проверяемый допуск к следующему переходу либо точный список недостающих частей.`}]}),(0,y.jsx)(`p`,{children:`Мы не начинаем с запуска полного набора команд. Сначала установим, что именно уже готово, затем выберем проверку для каждого уровня. История StudyHub содержит checkpoint B96 с commit c910d1142dd85df492fbffcc8eba1c5e9784363e и последующий readiness-тест B97. Это даёт точку для проверки, но не заменяет сверку текущего кода, журнала и результатов запуска. Первая практика отделяет сохранённые изменения от локального состояния и останавливает допуск только при конкретном неподтверждённом требовании.`}),(0,y.jsx)(`p`,{children:`Такая приёмка похожа на контрольный маршрут посылки: отметка на каждом отдельном участке полезна, но только полный путь показывает, дошёл ли отправленный предмет до нужного получателя. Если одна станция ещё не готова, мы называем её, а не ставим отметку за весь маршрут.`})]}),(0,y.jsxs)(s,{number:`01`,title:`Разные проверки отвечают на разные вопросы`,children:[(0,y.jsx)(o,{children:`Успешный тест полезен только в пределах того, что он действительно вызывает. Одна проверка репозитория не говорит, что API получил нужный provider, а ответ health не подтверждает сохранение задачи.`}),(0,y.jsx)(`p`,{children:`Сопоставим тип проверки с её доказательством. Локальная проверка операции отвечает, правильно ли работает отдельный метод на входе и выходе. HTTP-проверка проходит через маршрут, dependency, схему запроса и ответ. Проверка CLI подтверждает, что существующая команда получает свой сервис и освобождает ресурс. Сквозной сценарий связывает эти поверхности через общее сохранённое состояние.`}),(0,y.jsx)(h,{question:`Какие доказательства дают четыре уровня проверки готовности?`,hint:`Вспомните отдельно хранение, публичный HTTP-путь, ресурс CLI и межинтерфейсное состояние.`,answer:(0,y.jsxs)(`ol`,{children:[(0,y.jsx)(`li`,{children:`Тест SQL-репозитория подтверждает операцию чтения или изменения на уровне хранения.`}),(0,y.jsx)(`li`,{children:`HTTP-проверка подтверждает маршрут, dependency и прежний публичный ответ.`}),(0,y.jsx)(`li`,{children:`Проверка CLI подтверждает команду и её собственную область Session.`}),(0,y.jsx)(`li`,{children:`API → CLI → API подтверждает доступность изменения после нового запроса.`})]})}),(0,y.jsx)(`p`,{children:`Представим мост: проверка одного крепления на стенде не доказывает, что по всей конструкции можно безопасно проехать. Но и пробный проезд не подскажет, какое крепление неисправно, если тест собран из одних заглушек. Поэтому сначала сохраняем локальные доказательства по операциям, потом связываем API и CLI настоящей тестовой базой и при сбое возвращаемся к конкретной границе.`})]}),(0,y.jsxs)(s,{number:`02`,title:`Одна тестовая база, отдельная Session на действие`,children:[(0,y.jsx)(o,{children:`Тестовая среда должна быть похожа на реальный общий источник данных и при этом оставаться изолированной. Для этого файл SQLite принадлежит сценарию, а Session создаётся на короткую операцию.`}),(0,y.jsx)(`p`,{children:`Фикстура базы создаёт файл под tmp_path, явно поднимает уже согласованную исходную схему и выдаёт фабрику Session. Тестовый API направляется на этот адрес через существующую сборку или override dependency. CLI получает тот же адрес через свой контекст команды. После запроса и после CLI-команды закрываются их собственные Session. В конце восстанавливаются прежние overrides и настройки, а Engine освобождает файл.`}),(0,y.jsx)(`p`,{children:`Общий DATABASE_URL означает общий адрес базы, но не общий Python-объект Session. Сравним это с библиотекой: читатели смотрят в один каталог, а каждый получает отдельный формуляр выдачи. Передача всем запросам одного формуляра склеила бы независимые действия и могла бы спрятать ошибку времени жизни ресурса.`}),(0,y.jsx)(m,{caption:`Сквозная проверка на тестовой SQLite`,children:(0,y.jsxs)(p,{label:`От изолированной базы к независимой проверке`,children:[(0,y.jsx)(d,{title:`SQLite в tmp_path`,shape:`database`,children:(0,y.jsx)(`p`,{children:`Исходная схема и один тестовый адрес`})}),(0,y.jsx)(f,{label:`API открывает свою Session`}),(0,y.jsx)(d,{title:`HTTP-действие`,children:(0,y.jsx)(`p`,{children:`Существующий маршрут вызывает SQL-путь`})}),(0,y.jsx)(f,{label:`CLI открывает другую Session`}),(0,y.jsx)(d,{title:`CLI-команда`,children:(0,y.jsx)(`p`,{children:`Читает или меняет ту же запись`})}),(0,y.jsx)(f,{label:`Новый запрос перечитывает результат`}),(0,y.jsx)(d,{title:`Сверка договора`,children:(0,y.jsx)(`p`,{children:`Состояние и публичный ответ совпадают с ожидаемыми`})})]})}),(0,y.jsx)(`p`,{children:`Стрелки показывают последовательность действий, а не передачу одной Session между ними. Между HTTP-запросом и командой CLI остаётся файл базы. Независимый API-запрос снова получает ресурс и читает уже зафиксированное состояние. Такой путь позволяет отличить действительно сохранённую запись от объекта, который случайно остался в памяти предыдущего вызова.`}),(0,y.jsx)(l,{question:`Что должно совпадать у тестового API и CLI?`,options:[`Один адрес тестовой SQLite, отдельная Session для каждого запроса и команды`,`Один объект Session, переданный обоим интерфейсам`,`Рабочий DATABASE_URL, чтобы результат был ближе к production`],correctIndex:0,explanation:`Общее хранилище позволяет проверить обмен состоянием, а короткие ресурсы сохраняют независимый жизненный цикл каждого действия. Рабочая база в интеграционной фикстуре не участвует.`})]}),(0,y.jsxs)(s,{number:`03`,title:`Проверяем прежний договор, включая внутренние данные`,children:[(0,y.jsx)(o,{children:`Замена способа хранения не должна незаметно менять поведение Planner. Мы сверяем не только HTTP-статус, но и само состояние после операции.`}),(0,y.jsx)(t,{rows:[[(0,y.jsx)(`code`,{children:`HTTP`}),`Положительный id, прежние статусы, пустое тело DELETE и те же правила GET, POST, PUT и PATCH.`],[(0,y.jsx)(`code`,{children:`Выборка`}),`Фильтр, порядок и limit применяются так же, как в согласованном JSON-контракте.`],[(0,y.jsx)(`code`,{children:`Поиск и статистика`}),`Поиск сохраняет буквальную подстроку и нормализацию, внутренний all не путается с HTTP total.`],[(0,y.jsx)(`code`,{children:`Служебные маршруты`}),`preferences и health сохраняют прежний ответ и не зависят от SQL-переключения.`],[(0,y.jsx)(`code`,{children:`Состояние строки`}),`Внутренние tags остаются в БД, хотя публичный HTTP-ответ показывает прежние четыре поля.`]]}),(0,y.jsx)(`p`,{children:`В HTTP-наборе сохраняем проверки прежних предметных ошибок и используем follow_redirects=False, чтобы клиент не прошёл за нас редирект и не скрыл исходный статус или путь. Повторно используем уже хорошие тесты из предыдущих шагов. Не переписываем все операции в одну огромную проверку: отдельно остаются известные случаи PUT и PATCH, включая False, отсутствующие поля и явный null, а в сквозном сценарии добавляются только связи между интерфейсами.`}),(0,y.jsx)(`p`,{children:`Ответ маршрута может выглядеть верным, даже если после него потерялись tags или следующая Session не находит строку. Поэтому для ключевых изменений проверяем две стороны: клиентский результат и независимое чтение из тестовой базы. И наоборот, корректная строка в таблице не подтверждает HTTP-контракт, если маршрут поменял статус или тело ответа.`}),(0,y.jsx)(n,{code:[`# После API POST и команды CLI done(id)`,`response = client.get("/tasks/31")`,`assert response.json()["is_done"] is False`].join(`
`),question:`Какое ожидание противоречит сценарию, если новый GET читает ту же базу?`,options:[`GET использует адрес тестовой SQLite`,`is_done остаётся False после успешного CLI done`,`Ответ повторно получен новым HTTP-запросом`],correctIndex:1,explanation:`Команда done меняет сохранённое состояние. Поэтому новый GET должен увидеть True. Иначе мы либо проверяем неверный ожидаемый результат, либо интерфейсы не разделяют один источник.`,fix:`assert response.json()["is_done"] is True`}),(0,y.jsx)(r,{tone:`info`,children:`Тесты отдельных операций остаются полезными. Мы дополняем их одним связным сценарием, а не удаляем ради интеграционного теста.`})]}),(0,y.jsxs)(s,{number:`04`,title:`Импортируем репетиционную копию, не переключая источник`,children:[(0,y.jsx)(o,{children:`Импорт из предыдущего блока уже проверялся как отдельная команда. Здесь мы убеждаемся, что он встраивается в готовый SQL-путь и не выдаёт старую репетицию за актуальные рабочие данные.`}),(0,y.jsx)(`p`,{children:`Для прогона берём копию существующего JSON-файла и отдельную пустую SQLite с исходной схемой. Проверка источника завершается до записи: у снимка верный формат, нет дублирующихся id и не теряются предметные поля. Импорт сохраняет id, title, priority, is_done и tags. Колонка title_normalized вычисляется по знакомому правилу Python lower(). После импорта сверяем каждую запись независимым чтением, а не только количество строк.`}),(0,y.jsx)(`p`,{children:`Тестовая копия похожа на репетиционный журнал перед сменой расписания. Она помогает отработать порядок и сверить список, но не меняется вслед за исходным JSON. Если после копирования обычная команда добавила задачу, она не окажется в тестовой SQLite автоматически. Поэтому мы не используем эту базу в следующем шаге как готовый окончательный снимок.`}),(0,y.jsx)(`p`,{children:`После импорта проверяем обычное создание SQL-задачи и отсутствие конфликта её серверного id с уже перенесёнными значениями. Цель должна быть пустой до импорта. Повторный импорт в заполненную цель должен отказать без удаления или слияния строк. Такие границы позволяют отличить репетицию перехода от синхронизации двух хранилищ.`}),(0,y.jsx)(c,{statement:`Если число строк после импорта совпало с числом задач в копии JSON, мы уже доказали сохранность всех данных.`,isTrue:!1,explanation:`Совпадение количества не обнаруживает замену одной строки другой. Сравниваем идентификаторы и все предметные поля, включая tags, затем отдельно проверяем title_normalized.`})]}),(0,y.jsxs)(s,{number:`05`,title:`Связываем API, CLI и новые ресурсы`,children:[(0,y.jsx)(o,{children:`Теперь проверим путь, который связывает несколько действий. У каждого шага новый запрос или команда, а не сохранённый в тесте Planner с общей Session.`}),(0,y.jsx)(`p`,{children:`Начинаем с создания через API и сохраняем полученный id. CLI находит задачу по этому id и завершает её. Следующий API GET по тому же id видит is_done=true, а статистика отражает изменение. Для каждого интерфейса используется один тестовый адрес, но ресурс создаётся заново. При повторной сборке приложения и контекста CLI результат остаётся доступен через ту же SQLite.`}),(0,y.jsx)(`p`,{children:`Для проверки не требуется придумывать новую CLI-команду или второй сервис. Мы пользуемся уже созданными путями и проверяем то, что они обещают. Отдельные тесты предыдущих занятий по-прежнему отвечают за PUT, PATCH, DELETE, фильтр, порядок, limit, поиск, пустые значения, preferences, health и известные предметные ошибки. Новый межинтерфейсный сценарий показывает, что эти готовые части смотрят в одну базу.`}),(0,y.jsx)(`p`,{children:`Проверим также область ресурса на отказе и после повторного получения. Когда команда завершается, её Session закрывается даже при исключении. Следующая независимая команда создаёт новый ресурс и продолжает читать или менять данные. Для API аналогичную границу задаёт dependency с yield. На этом рубеже мы не вводим ещё одну абстракцию для транзакций: проверяем уже созданную границу.`}),(0,y.jsx)(r,{tone:`warn`,children:`Успешная повторная проверка через тот же объект не равна новому чтению. Мы создаём следующий запрос и следующий CLI-вызов, чтобы исключить случайный результат из кеша или незакрытого ресурса.`})]}),(0,y.jsxs)(s,{number:`06`,title:`Отказ до commit и решение о допуске`,children:[(0,y.jsx)(o,{children:`Готовность означает, что путь выдерживает и успешный сценарий, и контролируемый отказ. Мы проверяем сохранность данных до того, как разрешаем переход к рабочему снимку.`}),(0,y.jsx)(`p`,{children:`Используем подходящий механизм отказа, уже знакомый по работе с транзакцией: операция завершается ошибкой до commit. Затем новая Session проверяет, что частичная запись не появилась, а независимая следующая операция снова работает. Обычная JSON-сборка не переключается и не запускается как автоматический резервный путь. Если SQL-путь упал, тест показывает отказ, а не ложный успех через второе хранилище.`}),(0,y.jsx)(`p`,{children:`Составим таблицу допуска: критерий, выполненная проверка, фактический результат и статус. Для каждого пробела назовём конкретное место: операция, dependency, команда, настройки, данные или teardown фикстуры. Неготовую часть возвращаем к её шагу реализации и повторяем только затронутые проверки. Мы не пишем весь CRUD заново и не объявляем переход готовым, пока все обязательные доказательства отсутствуют.`}),(0,y.jsx)(`p`,{children:`Положительное решение даёт следующему занятию тестовую процедуру, перечень проверенных свойств и уверенность, что API и CLI могут использовать одну базу с отдельными ресурсами. Но источник истины остаётся прежним. В следующем шаге команда остановит новые записи в JSON, снимет актуальную копию, перенесёт её в подготовленную пустую цель и переключит оба интерфейса вместе.`}),(0,y.jsx)(r,{children:`Если точка B предыдущего занятия ещё не подтверждена, мы отмечаем конкретный блокер и не выдаём запланированный код за готовый. Проверки, независимые от отсутствующей части, можно выполнить на безопасной фикстуре.`})]}),(0,y.jsxs)(s,{number:`07`,title:`Что мы будем делать в практике`,children:[(0,y.jsx)(o,{children:`Проверим уже собранный путь на копии проекта и данных. Задача заканчивается проверяемым допуском либо ясным отказом с точным списком причин.`}),(0,y.jsx)(u,{variant:`connected`,items:[{title:`Сверить вход`,description:`Подтвердим кодом и журналом результаты предыдущих операций и ресурсных сборок. Неподтверждённый B96 останется блокером.`},{title:`Изолировать среду`,description:`Создадим одну SQLite в tmp_path, направим API и CLI на её адрес и дадим каждому действию свою Session.`},{title:`Повторить перенос`,description:`Импортируем копию JSON, сравним полные записи и проверим новое создание без конфликта id.`},{title:`Связать интерфейсы`,description:`Прогоним существующие проверки контракта и свяжем API create, CLI find/done, новый API get/stats на одном тестовом адресе.`},{title:`Зафиксировать допуск`,description:`Проверим отказ до commit, отсутствие JSON-fallback и оставим штатный JSON-путь нетронутым.`}]}),(0,y.jsx)(`p`,{children:`Блоки 01–06 объяснили, какое доказательство даёт каждая проверка, как изолировать ресурсы, что сравнивать после импорта и почему нужен новый запрос. Транзакция и импорт опираются на прежние занятия, но здесь проверяются внутри общего сценария. Если первая сверка не подтверждает завершение нужных шагов, зависимую часть не маскируем повторной реализацией.`}),(0,y.jsx)(`p`,{children:`К завершению у нас есть зафиксированные результаты на тестовой базе и проверка прежних возможностей. Рабочая JSON-база остаётся авторитетной до отдельной остановки записей и переноса окончательного снимка.`})]})]})}export{x as Lesson97};